+import {
+  Clock3,
+  MapPin,
+  RefreshCw,
+  UserCheck,
+  Users,
+} from "lucide-react";
+import { useCallback, useEffect, useRef, useState } from "react";
+import { Link } from "react-router-dom";
+
+const API_URL =
+  import.meta.env.VITE_API_URL ||
+  "http://localhost:5000/api/v1";
+
+function HospitalLiveQueue() {
+  const [queue, setQueue] = useState([]);
+  const [currentToken, setCurrentToken] = useState(null);
+  const [userToken, setUserToken] = useState(null);
+  const [peopleAhead, setPeopleAhead] = useState(0);
+  const [estimatedWait, setEstimatedWait] = useState(0);
+  const [error, setError] = useState("");
+  const [loading, setLoading] = useState(true);
+
+  const isMountedRef = useRef(true);
+  const requestInProgressRef = useRef(false);
+
+  // ======================================================
+  // NORMALIZE STATUS
+  // ======================================================
+
+  const normalizeStatus = (status) => {
+    return String(status || "waiting")
+      .trim()
+      .toLowerCase();
+  };
+
+  // ======================================================
+  // GET TOKEN NUMBER FOR SORTING
+  // ======================================================
+
+  const getTokenOrder = (token) => {
+    if (!token) {
+      return Number.MAX_SAFE_INTEGER;
+    }
+
+    const tokenNumber = String(
+      token.tokenNumber || ""
+    ).trim();
+
+    // Extract numeric part.
+    // Examples:
+    // H-001 -> 1
+    // H-12  -> 12
+    // 15    -> 15
+    const match = tokenNumber.match(/\d+/);
+
+    if (match) {
+      return Number(match[0]);
+    }
+
+    return Number.MAX_SAFE_INTEGER;
+  };
+
+  // ======================================================
+  // SORT WAITING QUEUE
+  // ======================================================
+
+  const sortQueue = (tokens) => {
+    return [...tokens].sort((a, b) => {
+      const aOrder = getTokenOrder(a);
+      const bOrder = getTokenOrder(b);
+
+      if (aOrder !== bOrder) {
+        return aOrder - bOrder;
+      }
+
+      // Fallback to creation time.
+      const aTime = new Date(
+        a.createdAt || 0
+      ).getTime();
+
+      const bTime = new Date(
+        b.createdAt || 0
+      ).getTime();
+
+      return aTime - bTime;
+    });
+  };
+
+  // ======================================================
+  // LOAD LIVE QUEUE
+  // ======================================================
+
+  const loadQueue = useCallback(async () => {
+    // Prevent overlapping requests.
+    if (requestInProgressRef.current) {
+      return;
+    }
+
+    requestInProgressRef.current = true;
+
+    try {
+      if (isMountedRef.current) {
+        setError("");
+      }
+
+      // --------------------------------------------------
+      // GET SAVED APPOINTMENT
+      // --------------------------------------------------
+
+      const savedToken = localStorage.getItem(
+        "queueless_hospital_token"
+      );
+
+      if (!savedToken) {
+        if (isMountedRef.current) {
+          setError(
+            "No hospital appointment found."
+          );
+          setLoading(false);
+        }
+
+        return;
+      }
+
+      // --------------------------------------------------
+      // PARSE APPOINTMENT
+      // --------------------------------------------------
+
+      let parsedToken;
+
+      try {
+        parsedToken = JSON.parse(savedToken);
+      } catch {
+        if (isMountedRef.current) {
+          setError(
+            "Invalid appointment data."
+          );
+          setLoading(false);
+        }
+
+        return;
+      }
+
+      // --------------------------------------------------
+      // GET HOSPITAL ID
+      // --------------------------------------------------
+
+      const hospitalId =
+        parsedToken?.hospital?._id ||
+        parsedToken?.hospital?.id ||
+        parsedToken?.hospitalId ||
+        parsedToken?.hospital;
+
+      // --------------------------------------------------
+      // GET DOCTOR ID
+      // --------------------------------------------------
+
+      const doctorId =
+        parsedToken?.doctor?._id ||
+        parsedToken?.doctor?.id ||
+        parsedToken?.doctorId ||
+        parsedToken?.doctor;
+
+      if (!hospitalId || !doctorId) {
+        if (isMountedRef.current) {
+          setError(
+            "Hospital or doctor information is missing."
+          );
+          setLoading(false);
+        }
+
+        return;
+      }
+
+      // --------------------------------------------------
+      // API REQUEST
+      // --------------------------------------------------
+
+      const url =
+        `${API_URL}/hospitals/queue/status` +
+        `?hospitalId=${encodeURIComponent(
+          hospitalId
+        )}` +
+        `&doctorId=${encodeURIComponent(
+          doctorId
+        )}`;
+
+      const response = await fetch(url);
+
+      const data = await response.json();
+
+      if (!response.ok) {
+        throw new Error(
+          data?.message ||
+            "Unable to load live queue."
+        );
+      }
+
+      // --------------------------------------------------
+      // GET QUEUE
+      // --------------------------------------------------
+
+      const latestQueue = Array.isArray(
+        data?.queue
+      )
+        ? data.queue
+        : [];
+
+      // --------------------------------------------------
+      // FIND USER TOKEN
+      // --------------------------------------------------
+
+      const latestToken =
+        latestQueue.find(
+          (token) =>
+            String(token?._id) ===
+            String(parsedToken?._id)
+        ) || parsedToken;
+
+      // --------------------------------------------------
+      // NORMALIZE QUEUE
+      // --------------------------------------------------
+
+      const normalizedQueue =
+        latestQueue.map((token) => ({
+          ...token,
+          normalizedStatus:
+            normalizeStatus(token?.status),
+        }));
+
+      // --------------------------------------------------
+      // SORT WAITING TOKENS
+      // --------------------------------------------------
+
+      const waitingTokens = sortQueue(
+        normalizedQueue.filter(
+          (token) =>
+            token.normalizedStatus ===
+            "waiting"
+        )
+      );
+
+      // --------------------------------------------------
+      // FIND USER POSITION
+      // --------------------------------------------------
+
+      const userStatus =
+        normalizeStatus(
+          latestToken?.status
+        );
+
+      const userIndex =
+        waitingTokens.findIndex(
+          (token) =>
+            String(token?._id) ===
+            String(parsedToken?._id)
+        );
+
+      // --------------------------------------------------
+      // PEOPLE AHEAD
+      // --------------------------------------------------
+
+      let calculatedPeopleAhead = 0;
+
+      if (userStatus === "waiting") {
+        calculatedPeopleAhead =
+          userIndex >= 0
+            ? userIndex
+            : 0;
+      } else {
+        calculatedPeopleAhead = 0;
+      }
+
+      // --------------------------------------------------
+      // AVERAGE CONSULTATION TIME
+      // --------------------------------------------------
+
+      const averageTime =
+        Number(
+          latestToken?.doctor
+            ?.averageConsultationTime
+        ) || 15;
+
+      // --------------------------------------------------
+      // ESTIMATED WAIT
+      // --------------------------------------------------
+
+      const calculatedEstimatedWait =
+        userStatus === "waiting"
+          ? calculatedPeopleAhead *
+            averageTime
+          : 0;
+
+      // --------------------------------------------------
+      // CURRENT TOKEN
+      // --------------------------------------------------
+
+      const latestCurrentToken =
+        data?.currentToken || null;
+
+      // --------------------------------------------------
+      // UPDATE STATE
+      // --------------------------------------------------
+
+      if (isMountedRef.current) {
+        setQueue(normalizedQueue);
+
+        setCurrentToken(
+          latestCurrentToken
+        );
+
+        setUserToken({
+          ...latestToken,
+          normalizedStatus:
+            userStatus,
+        });
+
+        setPeopleAhead(
+          calculatedPeopleAhead
+        );
+
+        setEstimatedWait(
+          calculatedEstimatedWait
+        );
+
+        setLoading(false);
+      }
+
+      // --------------------------------------------------
+      // SAVE LATEST TOKEN
+      // --------------------------------------------------
+
+      localStorage.setItem(
+        "queueless_hospital_token",
+        JSON.stringify(latestToken)
+      );
+    } catch (err) {
+      console.error(
+        "Hospital queue error:",
+        err
+      );
+
+      if (isMountedRef.current) {
+        setError(
+          err?.message ||
+            "Unable to load live queue."
+        );
+
+        setLoading(false);
+      }
+    } finally {
+      requestInProgressRef.current =
+        false;
+    }
+  }, []);
+
+  // ======================================================
+  // AUTOMATIC LIVE QUEUE REFRESH
+  // ======================================================
+
+  useEffect(() => {
+    isMountedRef.current = true;
+
+    let timeoutId;
+
+    const pollQueue = async () => {
+      await loadQueue();
+
+      if (!isMountedRef.current) {
+        return;
+      }
+
+      // Wait 5 seconds AFTER the request finishes.
+      timeoutId = setTimeout(
+        pollQueue,
+        5000
+      );
+    };
+
+    pollQueue();
+
+    return () => {
+      isMountedRef.current = false;
+
+      if (timeoutId) {
+        clearTimeout(timeoutId);
+      }
+    };
+  }, [loadQueue]);
+
+  // ======================================================
+  // USER STATUS
+  // ======================================================
+
+  const userStatus =
+    normalizeStatus(
+      userToken?.status
+    );
+
+  // ======================================================
+  // STATUS DISPLAY
+  // ======================================================
+
+  const getStatusLabel = () => {
+    switch (userStatus) {
+      case "serving":
+      case "called":
+      case "in_progress":
+      case "in-progress":
+        return "YOUR TURN";
+
+      case "completed":
+        return "COMPLETED";
+
+      case "skipped":
+        return "SKIPPED";
+
+      case "waiting":
+      default:
+        return "WAITING";
+    }
+  };
+
+  const getStatusMessage = () => {
+    switch (userStatus) {
+      case "serving":
+      case "called":
+      case "in_progress":
+      case "in-progress":
+        return "Please proceed to the consultation area.";
+
+      case "completed":
+        return "Your appointment has been completed.";
+
+      case "skipped":
+        return "Your token was skipped by the hospital.";
+
+      case "waiting":
+      default:
+        return "Please wait for your token to be called.";
+    }
+  };
+
+  // ======================================================
+  // STATUS STYLE
+  // ======================================================
+
+  const getStatusStyle = () => {
+    switch (userStatus) {
+      case "serving":
+      case "called":
+      case "in_progress":
+      case "in-progress":
+        return "bg-green-600";
+
+      case "completed":
+        return "bg-slate-700";
+
+      case "skipped":
+        return "bg-orange-600";
+
+      case "waiting":
+      default:
+        return "bg-blue-700";
+    }
+  };
+
+  // ======================================================
+  // RENDER
+  // ======================================================
+
+  return (
+    <main className="min-h-screen bg-slate-50 px-6 py-10">
+      <div className="mx-auto max-w-5xl">
+
+        {/* BACK */}
+
+        <Link
+          to="/hospitals"
+          className="font-semibold text-blue-700"
+        >
+          ← Back to Hospitals
+        </Link>
+
+        {/* HEADER */}
+
+        <div className="mt-6 flex items-center justify-between">
+          <div>
+            <h1 className="text-3xl font-bold text-slate-900">
+              Hospital Live Queue
+            </h1>
+
+            <p className="mt-2 text-slate-500">
+              Track your appointment in real time.
+            </p>
+          </div>
+
+          <button
+            onClick={loadQueue}
+            disabled={loading}
+            className="flex items-center gap-2 rounded-xl border bg-white px-4 py-3 font-semibold shadow-sm hover:bg-slate-50 disabled:opacity-50"
+          >
+            <RefreshCw
+              className={`h-4 w-4 ${
